// 18-tap direct-form FIR, 8-bit samples, PIPELINED -> shorter register-to-register
// path (longer per-stage constant-time delay -> higher Fmax). Same transfer function
// as the reference up to a fixed extra latency.
module firr18_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
